/**
 * WordPress dependencies
 */
import apiFetch from '@safe-wordpress/api-fetch';
import { useDispatch, useSelect } from '@safe-wordpress/data';
import { useCallback, useEffect } from '@safe-wordpress/element';

/**
 * External dependencies
 */
import { quotaPercentageToColor } from '@nab/utils';
import type { Experiment, Maybe, CommercialOpportunity } from '@nab/types';

/**
 * Internal dependencies
 */
import { store as NAB_DATA } from './store';
import type { State } from './store/types';

export function useCommercialOpportunity(): CommercialOpportunity {
	const isSubscribed = useIsSubscribed();
	return useSelect(
		( select ): CommercialOpportunity => {
			const { hasCapability, getPluginSetting } = select( NAB_DATA );
			const canManageSubscription =
				hasCapability( 'manage_nab_account' ) &&
				! getPluginSetting( 'areSubscriptionControlsDisabled' );

			if ( ! canManageSubscription ) {
				return { type: 'none' };
			}

			const quota = select( NAB_DATA ).getQuota();
			if ( ! quota ) {
				return { type: 'none' };
			}

			const { isSubscribedTo } = select( NAB_DATA );
			const subscribedAction = isSubscribedTo( 'enterprise' )
				? 'purchase-quota-or-upgrade'
				: 'upgrade';
			const action = isSubscribed ? subscribedAction : 'subscribe';

			if ( ! quota.availableQuota ) {
				return { type: 'quota-exhausted', action };
			}

			if ( quota.boostExpiration ) {
				if ( isSubscribed ) {
					return { type: 'none' };
				}

				const today = select( NAB_DATA ).getToday();
				if (
					today < quota.boostExpiration &&
					gapInDays( today, quota.boostExpiration ) < 3
				) {
					return { type: 'boost-expiring', action };
				}
			}

			const color = quotaPercentageToColor( quota.percentage );
			return 'bad' === color
				? { type: 'low-quota', action }
				: { type: 'none' };
		},
		[ isSubscribed ]
	);
}

export const useIsSubscribed = (): boolean =>
	useSelect( ( select ) => select( NAB_DATA ).isSubscribedTo( 'basic' ), [] );

export function useExperimentAttribute< K extends keyof Experiment >(
	attr: K,
	defaultValue: Experiment[ K ]
): Experiment[ K ] {
	return useSelect(
		( select ) => {
			const { getPageAttribute, getExperimentAttribute } =
				select( NAB_DATA );
			const exp = getPageAttribute( 'editor/activeExperiment' );
			return exp
				? ( getExperimentAttribute( exp, attr ) ?? defaultValue )
				: defaultValue;
		},
		[ attr, defaultValue ]
	);
}

type PageAttributes = Required< State[ 'page' ] >;
export function usePageAttribute< A extends keyof PageAttributes >(
	attr: A,
	defaultValue: PageAttributes[ A ]
): [ PageAttributes[ A ], ( v: PageAttributes[ A ] ) => void ] {
	const actualValue: Maybe< PageAttributes[ A ] > = useSelect(
		( select ) =>
			select( NAB_DATA ).getPageAttribute( attr ) as PageAttributes[ A ],
		[ attr ]
	);
	const { setPageAttribute } = useDispatch( NAB_DATA );

	useEffect( () => {
		if ( actualValue ) {
			return;
		}
		void setPageAttribute( attr, defaultValue );
	}, [ attr, actualValue, defaultValue, setPageAttribute ] );

	const value = actualValue ?? defaultValue;

	const setValue = useCallback(
		( v: PageAttributes[ A ] ) => setPageAttribute( attr, v ),
		[ attr, setPageAttribute ]
	);

	return [ value, setValue ];
}

type PluginSettings = State[ 'settings' ][ 'nelio' ];
export function usePluginSetting< A extends keyof PluginSettings >(
	attr: A
): PluginSettings[ A ] {
	return useSelect(
		( select ) => select( NAB_DATA ).getPluginSetting( attr ),
		[ attr ]
	);
}

export const useAdminUrl = (
	path: string,
	args: Record< string, string | boolean | number >
): string =>
	useSelect(
		( select ) => select( NAB_DATA ).getAdminUrl( path, args ),
		[ path, args ]
	);

const synchedActivities: Array< string > = [];
export const useActivityEffect = (
	data: Maybe< Record< string, unknown > >
) => {
	const apiUrl = usePluginSetting( 'apiUrl' );
	const siteId = usePluginSetting( 'siteId' );
	useEffect( () => {
		if ( ! data ) {
			return;
		}

		const stringified = JSON.stringify( data );
		if ( synchedActivities.includes( stringified ) ) {
			return;
		}

		void apiFetch( {
			url: `${ apiUrl }/site/${ siteId }/subscription/activity`,
			credentials: 'omit',
			method: 'POST',
			mode: 'cors',
			data,
		} ).then( () => synchedActivities.push( stringified ) );
	}, [ apiUrl, siteId, data ] );
};

// =======
// HELPERS
// =======

function gapInDays( a: string, b: string ): number {
	a = a.substring( 0, 10 ) + 'T10:00:00.000Z';
	b = b.substring( 0, 10 ) + 'T10:00:00.000Z';
	return (
		Math.abs( new Date( a ).getTime() - new Date( b ).getTime() ) /
		( 24 * 60 * 60 * 1000 )
	);
}
