/**
 * External dependencies
 */
import type {
	AlternativeId,
	CssEditorState,
	CssSelectorFinderState,
	ECommercePlugin,
	EntityId,
	EntityInstance,
	EntityKind,
	EntityKindName,
	Experiment,
	ExperimentId,
	ExperimentSuggestion,
	ExperimentTypeName,
	ExportSettings,
	FastSpringProduct,
	FinishedExperimentSummary,
	GoalId,
	JavaScriptEditorState,
	Maybe,
	MediaId,
	Menu,
	MenuId,
	Opportunity,
	OptimizationScore,
	OrderStatus,
	PendingExperimentSummary,
	PluginSettings,
	Quota,
	QuotaBoost,
	Results,
	ReusableGoal,
	ReusableSegment,
	RunningExperimentSummary,
	SegmentId,
	Template,
	TemplateContextGroup,
	TemplateContextGroupName,
	Theme,
	ThemeId,
	Url,
	WelcomeStatus,
} from '@nab/types';

export type State = {
	readonly entities: {
		readonly config: ReadonlyArray< EntityKind >;
		readonly data: Record<
			EntityKindName,
			Partial< Record< EntityId, EntityInstance > >
		>;
	};

	readonly experiments: Partial< Record< ExperimentId, Experiment > >;

	readonly fastspring: {
		readonly currency: string;
		readonly products: ReadonlyArray< FastSpringProduct >;
		readonly subscriptionId: string;
	};

	readonly media: Partial< Record< MediaId, Url > >;

	readonly page: PageAttributes;

	readonly recommendationEngine: {
		readonly score: OptimizationScore;
		readonly opportunities: ReadonlyArray< Opportunity >;
		readonly instantiatingOpportunity?: Opportunity;
		readonly experiments: {
			readonly exist: boolean;
			readonly pendingSummaries: ReadonlyArray< PendingExperimentSummary >;
			readonly recentCount: number;
			readonly recentSummaries: ReadonlyArray< FinishedExperimentSummary >;
			readonly runningCount: number;
			readonly runningSummaries: ReadonlyArray< RunningExperimentSummary >;
		};
		readonly suggestionGenerationState:
			| {
					readonly status: 'idle' | 'scanning-opportunity';
			  }
			| {
					readonly status: 'opportunity-scan-ready';
					readonly opportunity: Opportunity;
					readonly suggestions: ReadonlyArray< ExperimentSuggestion >;
					readonly instantiatingSuggestion?: ExperimentSuggestion;
			  };
	};

	readonly results: Partial< Record< ExperimentId, Results > >;

	readonly reusableEntities: {
		readonly isSavingEntities: boolean;
		readonly goals: ReadonlyArray< ReusableGoal >;
		readonly segments: ReadonlyArray< ReusableSegment >;
	};

	readonly settings: {
		readonly today: string;
		readonly language: string;
		readonly menus: Partial< Record< MenuId, Menu > >;
		readonly nelio: PluginSettings;
		readonly plugins: ReadonlyArray< string >;
		readonly templateContexts: Record<
			TemplateContextGroupName,
			TemplateContextGroup
		>;
		readonly templates: Record< EntityKindName, ReadonlyArray< Template > >;
		readonly themes: Partial< Record< ThemeId, Theme > >;
		readonly ecommerce: Record< ECommercePlugin, ECommerceSettings >;
	};

	readonly siteQuota: Maybe< Quota >;
};

export type ECommerceSettings = {
	readonly currency: string;
	readonly currencyPosition: 'before' | 'after';
	readonly currencySymbol: string;
	readonly decimalSeparator: string;
	readonly numberOfDecimals: number;
	readonly orderStatuses: ReadonlyArray< OrderStatus >;
	readonly thousandsSeparator: string;
};

// ============
// HELPER TYPES
// ============

type PageAttributes = {
	readonly isLocked: boolean;
	readonly sidebarDimensions: {
		readonly top: number;
		readonly height: string;
		readonly applyFix: boolean;
	};

	readonly 'account/usesFullViewAgency'?: boolean;

	readonly 'chatbot/status': boolean;

	readonly 'css-preview/areControlsVisible'?: boolean;
	readonly 'css-preview/activeResolution'?: 'desktop' | 'tablet' | 'mobile';
	readonly 'css-selector/cssSelectorFinderState'?: CssSelectorFinderState;
	readonly 'css-selector/openedCssSelectorFinderId'?: number | string;
	readonly 'css-editor/cssEditorState'?: CssEditorState;

	readonly 'components/javascriptGlobals'?: ReadonlyArray< string >;

	readonly 'php-preview/areControlsVisible'?: boolean;
	readonly 'php-preview/activeResolution'?: 'desktop' | 'tablet' | 'mobile';

	readonly 'editor/activeExperiment'?: ExperimentId;
	readonly 'editor/activeExperimentType'?: ExperimentTypeName;
	readonly 'editor/activeGoal'?: GoalId;
	readonly 'editor/activeSegment'?: SegmentId;
	readonly 'editor/alternativeInPreviewDialog'?: AlternativeId | false;
	readonly 'editor/isExperimentBeingPaused'?: boolean;
	readonly 'editor/isExperimentBeingStopped'?: boolean;

	readonly 'results/alternativeBeingApplied'?: AlternativeId | false;
	readonly 'results/alternativeToApply'?: AlternativeId | false;
	readonly 'results/exportSettings'?: ExportSettings;
	readonly 'results/isCreatingFollowUpTest'?: boolean;
	readonly 'results/isExportModalOpen'?: boolean;
	readonly 'results/isExporting'?: boolean;
	readonly 'results/isPublicView'?: boolean;
	readonly 'results/isReadOnlyActive'?: boolean;
	readonly 'results/timeGrouping'?: 'daily' | 'weekly' | 'monthly';
	readonly 'results/shouldShowUniqueResults'?: boolean;

	readonly 'javascript-editor/javascriptEditorState'?: JavaScriptEditorState;

	readonly 'menus/isConfirmationDialogForMenuDuplicationVisible'?: boolean;
	readonly 'menus/isDuplicatingMenu'?: boolean;

	readonly 'welcome/status'?: WelcomeStatus;
	readonly 'welcome/quota-boost'?: QuotaBoost;

	readonly 'widgets/isConfirmationDialogForWidgetDuplicationVisible'?: boolean;
	readonly 'widgets/isDuplicatingWidgets'?: boolean;
};
